<script>
  import { createEventDispatcher, onMount } from 'svelte';
  import { push } from 'svelte-spa-router';
  import { authStore, projectStore, uiStore } from '../stores/index.js';
  import { projectsApi, categoriesApi } from '../services/database.js';
  import { getRoleLabel, canManageUsers } from '../constants/roles.js';
  import Sidebar from '../components/Sidebar.svelte';
  import ChangePassword from '../components/ChangePassword.svelte';
  import CreateProjectForm from '../components/CreateProjectForm.svelte';

  const dispatch = createEventDispatcher();

  let sidebarCollapsed = false;
  let user = null;
  let role = null;
  let projectsLoaded = false;

  // Subscribe to stores
  authStore.subscribe(state => {
    user = state.user;
    role = state.role;
  });

  uiStore.subscribe(state => {
    sidebarCollapsed = state.sidebarCollapsed;
  });

  // 当 user 变化且存在时，加载项目（确保登录后立即加载）
  $: if (user && !projectsLoaded) {
    loadProjects();
  }

  onMount(async () => {
    if (user && !projectsLoaded) {
      await loadProjects();
    }
  });

  async function loadProjects() {
    projectsLoaded = true; // 标记为已开始加载，防止重复调用
    projectStore.setLoading(true);
    try {
      const result = await projectsApi.list();
      if (result.data) {
        // Load categories for each project
        const projectsWithCategories = await Promise.all(
          result.data.map(async (project) => {
            const catResult = await categoriesApi.listByProject(project.$id);
            return {
              ...project,
              categories: catResult.data || []
            };
          })
        );
        projectStore.setProjects(projectsWithCategories);
      }
    } catch (error) {
      console.error('Failed to load projects:', error);
      projectsLoaded = false; // 加载失败时允许重试
    }
  }

  function toggleSidebar() {
    uiStore.toggleSidebar();
  }

  function handleLogout() {
    dispatch('logout');
  }

  function handleCreateProject() {
    uiStore.openModal('createProject');
  }
</script>

<div class="layout" class:collapsed={sidebarCollapsed}>
  <!-- Sidebar -->
  <aside class="sidebar">
    <div class="sidebar-header">
      <a href="/" class="logo">
        {#if !sidebarCollapsed}
          <span class="logo-icon">🏗️</span>
          <span class="logo-text">建材管理系统</span>
        {:else}
          <span class="logo-icon">🏗️</span>
        {/if}
      </a>
      <button class="toggle-btn" on:click={toggleSidebar}>
        {sidebarCollapsed ? '→' : '←'}
      </button>
    </div>
    
    <Sidebar collapsed={sidebarCollapsed} on:createProject={handleCreateProject} />
  </aside>

  <!-- Main Content -->
  <div class="main-wrapper">
    <!-- Header -->
    <header class="header">
      <div class="header-left">
        <h1 class="page-title">建筑材料管理系统</h1>
      </div>
      <div class="header-right">
        {#if canManageUsers(role)}
          <button class="header-btn" on:click={() => push('/users')}>
            👤 用户管理
          </button>
        {/if}
        <ChangePassword />
        <div class="user-info">
          <span class="user-role">{getRoleLabel(role)}</span>
          <span class="user-name">{user?.username || user?.email || '用户'}</span>
        </div>
        <button class="logout-btn" on:click={handleLogout}>
          退出登录
        </button>
      </div>
    </header>

    <!-- Content Area -->
    <main class="content">
      <slot />
    </main>
  </div>
</div>

<!-- Create Project Modal -->
{#if $uiStore.activeModal === 'createProject'}
  <div class="modal-overlay" on:click={() => uiStore.closeModal()} on:keydown={(e) => e.key === 'Escape' && uiStore.closeModal()} role="button" tabindex="-1">
    <div class="modal" on:click|stopPropagation>
      <div class="modal-header">
        <h2>创建新项目</h2>
        <button class="close-btn" on:click={() => uiStore.closeModal()}>×</button>
      </div>
      <div class="modal-body">
        <CreateProjectForm on:created={loadProjects} />
      </div>
    </div>
  </div>
{/if}

